-- Independently generated read-only Gold v2 SQL oracles for the MGC-230 fixture.
-- Source/measure/group metadata follows the fixture and checked Gold v2 catalog.
-- Result arrays use stable ordering; satisfaction averages cast ratings to numeric.
-- Results are observed data only; this file does not evaluate readiness or the F1 route.
BEGIN TRANSACTION READ ONLY;
SELECT 'MGC-001'::text AS case_id, 'billing.revenue'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT SUM("receita_total_reais") AS "valor" FROM "gold_v2"."diagnostico_receita" WHERE "municipio" = 'RECIFE' AND "competencia" = '2026-06' ) q
UNION ALL
SELECT 'MGC-002'::text AS case_id, 'energy.consumption'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT "classe_consumo" AS "classe_consumo", SUM("consumo_total_kwh") AS "valor" FROM "gold_v2"."diagnostico_receita" WHERE "municipio" = 'RECIFE' AND "competencia" = '2026-06' GROUP BY "classe_consumo") q
UNION ALL
SELECT 'MGC-003'::text AS case_id, 'energy.average_consumption_per_uc'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT SUM("consumo_total_kwh") / NULLIF(SUM("qtd_ucs_com_leitura"), 0) AS "valor", SUM("consumo_total_kwh") AS "numerador", SUM("qtd_ucs_com_leitura") AS "denominador" FROM "gold_v2"."diagnostico_receita" WHERE "municipio" = 'RECIFE' AND "competencia" = '2026-06' ) q
UNION ALL
SELECT 'MGC-004'::text AS case_id, 'energy.gd_units'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT COUNT(DISTINCT "id_uc") AS "valor" FROM "gold_v2"."variacao_consumo_uc" WHERE "possui_gd" = 'Sim' ) q
UNION ALL
SELECT 'MGC-005'::text AS case_id, 'energy.gd_consumption_drop'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT COUNT(DISTINCT "id_uc") AS "valor", COUNT(*) FILTER (WHERE "queda_consumo_superior_30_pct" IS TRUE) AS "flags_true_total" FROM "gold_v2"."variacao_consumo_uc" WHERE "possui_gd" = 'Sim' AND "possui_gd" = 'Sim' AND "meses_com_leitura_p1" >= 6 AND "meses_com_leitura_p2" >= 6 AND "queda_consumo_superior_30_pct" IS TRUE ) q
UNION ALL
SELECT 'MGC-006'::text AS case_id, 'network.equivalent_interruption_duration'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT "id_alimentador" AS "id_alimentador", "competencia" AS "competencia", "DEC" AS "valor" FROM "gold_v2"."indicadores_dec_fec" WHERE "id_alimentador" = 'ALM-ABR-001' AND "competencia" BETWEEN '2026-01' AND '2026-06' GROUP BY "id_alimentador", "competencia") q
UNION ALL
SELECT 'MGC-006'::text AS case_id, 'network.equivalent_interruption_frequency'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT "id_alimentador" AS "id_alimentador", "competencia" AS "competencia", "FEC" AS "valor" FROM "gold_v2"."indicadores_dec_fec" WHERE "id_alimentador" = 'ALM-ABR-001' AND "competencia" BETWEEN '2026-01' AND '2026-06' GROUP BY "id_alimentador", "competencia") q
UNION ALL
SELECT 'MGC-007'::text AS case_id, 'service.satisfaction'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT AVG("nota_satisfacao"::numeric) AS "valor" FROM "gold_v2"."atendimentos_uc" WHERE "data_abertura" >= TIMESTAMPTZ '2026-06-01 00:00:00+00' AND "data_abertura" < TIMESTAMPTZ '2026-07-01 00:00:00+00' ) q
UNION ALL
SELECT 'MGC-008'::text AS case_id, 'service.attendance'::text AS metric_id, 'period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result FROM (SELECT COUNT(DISTINCT "protocolo") AS "valor" FROM "gold_v2"."atendimentos_uc" WHERE "data_abertura" >= TIMESTAMPTZ '2026-06-01 00:00:00+00' AND "data_abertura" < TIMESTAMPTZ '2026-07-01 00:00:00+00' ) q
