SELECT 'MGC-184'::text AS case_id, 'network.weighted_continuity_period'::text AS metric_id, 'weighted_period'::text AS period_label, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)::text), '[]'::jsonb)::text AS result
FROM (
    SELECT id_alimentador,
           COUNT(DISTINCT competencia) AS competencias,
           MIN(total_ucs_alimentador) AS denominador_min,
           MAX(total_ucs_alimentador) AS denominador_max,
           COUNT(*) FILTER (WHERE duracao_total_interrupcoes_horas IS NOT NULL) AS meses_dec_validos,
           COUNT(*) FILTER (WHERE frequencia_total_interrupcoes IS NOT NULL) AS meses_fec_validos,
           SUM(duracao_total_interrupcoes_horas) AS numerador_dec,
           SUM(frequencia_total_interrupcoes) AS numerador_fec,
           CASE WHEN COUNT(DISTINCT competencia) = 6
                     AND MIN(total_ucs_alimentador) > 0
                     AND MIN(total_ucs_alimentador) = MAX(total_ucs_alimentador)
                     AND COUNT(*) FILTER (WHERE duracao_total_interrupcoes_horas IS NOT NULL) = 6
                THEN SUM(duracao_total_interrupcoes_horas) / MIN(total_ucs_alimentador)
           END AS dec_ponderado_horas_por_uc,
           CASE WHEN COUNT(DISTINCT competencia) = 6
                     AND MIN(total_ucs_alimentador) > 0
                     AND MIN(total_ucs_alimentador) = MAX(total_ucs_alimentador)
                     AND COUNT(*) FILTER (WHERE frequencia_total_interrupcoes IS NOT NULL) = 6
                THEN SUM(frequencia_total_interrupcoes)::numeric / MIN(total_ucs_alimentador)
           END AS fec_ponderado_interrupcoes_por_uc
    FROM gold_v2.indicadores_dec_fec
    WHERE id_alimentador = 'ALM-ABR-001'
      AND competencia BETWEEN '2026-01' AND '2026-06'
    GROUP BY id_alimentador
) q
UNION ALL
